        CONSTRAINT "PK_TestCases" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_TestCases_TestCasePriorities_PriorityId" FOREIGN KEY ("PriorityId") REFERENCES "TestCasePriorities" ("Id") ON DELETE CASCADE,
