END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260214041238_InitialCreate') THEN
    CREATE TABLE test_executions (
        id uuid NOT NULL,
        test_case_id uuid NOT NULL,
        tester_id uuid NOT NULL,
        status_id integer NOT NULL,
        notes character varying(2000),
        execution_date timestamp with time zone NOT NULL DEFAULT (NOW()),
        completed_at timestamp with time zone,
        CONSTRAINT "PK_test_executions" PRIMARY KEY (id),
        CONSTRAINT "FK_test_executions_TestCases_test_case_id" FOREIGN KEY (test_case_id) REFERENCES "TestCases" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_test_executions_Users_tester_id" FOREIGN KEY (tester_id) REFERENCES "Users" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_test_executions_execution_statuses_status_id" FOREIGN KEY (status_id) REFERENCES execution_statuses (id) ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
