        "Id" uuid NOT NULL,
        "TestExecutionId" uuid NOT NULL,
        "FileTypeId" integer NOT NULL,
        "FileName" text NOT NULL,
        "FilePath" text NOT NULL,
        "FileSize" bigint NOT NULL,
        "ContentType" text NOT NULL,
        "Description" text,
        "UploadedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Evidences" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Evidences_EvidenceTypes_FileTypeId" FOREIGN KEY ("FileTypeId") REFERENCES "EvidenceTypes" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Evidences_test_executions_TestExecutionId" FOREIGN KEY ("TestExecutionId") REFERENCES test_executions (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260214041238_InitialCreate') THEN
