        "Id" uuid NOT NULL,
        "TestExecutionId" uuid NOT NULL,
        "TestStepId" uuid NOT NULL,
        "StatusId" integer NOT NULL,
        "ActualResult" text,
        "Notes" text,
        "EvaluatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ExecutionStepResults" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ExecutionStepResults_StepResultStatuses_StatusId" FOREIGN KEY ("StatusId") REFERENCES "StepResultStatuses" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ExecutionStepResults_TestSteps_TestStepId" FOREIGN KEY ("TestStepId") REFERENCES "TestSteps" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ExecutionStepResults_test_executions_TestExecutionId" FOREIGN KEY ("TestExecutionId") REFERENCES test_executions (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

