        created_by_user_id uuid,
        updated_at timestamp with time zone,
        updated_by_user_id uuid,
        CONSTRAINT "PK_requirements" PRIMARY KEY (id),
        CONSTRAINT "FK_requirements_projects_project_id" FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
        CONSTRAINT "FK_requirements_users_created_by_user_id" FOREIGN KEY (created_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_requirements_users_deleted_by_user_id" FOREIGN KEY (deleted_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
