            nextval(pg_get_serial_sequence('project_priorities', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('requirement_complexities', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM requirement_complexities) + 1,
            nextval(pg_get_serial_sequence('requirement_complexities', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('requirement_priorities', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM requirement_priorities) + 1,
            nextval(pg_get_serial_sequence('requirement_priorities', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('requirement_statuses', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM requirement_statuses) + 1,
            nextval(pg_get_serial_sequence('requirement_statuses', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('requirement_types', 'Id'),
        GREATEST(
