DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260719173450_AddDefectsAndCoverage') THEN
    CREATE TABLE defects (
        id uuid NOT NULL,
        project_id uuid NOT NULL,
        test_case_id uuid,
        test_execution_id uuid,
        title character varying(300) NOT NULL,
        description character varying(3000),
        steps_to_reproduce character varying(3000),
        actual_result character varying(2000),
        expected_result character varying(2000),
        defect_priority_id integer NOT NULL,
        defect_status_id integer NOT NULL,
        reported_by_user_id uuid NOT NULL,
        assigned_to_user_id uuid,
        resolved_at timestamp with time zone,
        resolution_notes character varying(2000),
        is_deleted boolean NOT NULL DEFAULT FALSE,
        deleted_at timestamp with time zone,
        deleted_by_user_id uuid,
        created_at timestamp with time zone NOT NULL,
        created_by_user_id uuid,
        updated_at timestamp with time zone,
        updated_by_user_id uuid,
        CONSTRAINT "PK_defects" PRIMARY KEY (id),
        CONSTRAINT "FK_defects_defect_priorities_defect_priority_id" FOREIGN KEY (defect_priority_id) REFERENCES defect_priorities (id) ON DELETE RESTRICT,
        CONSTRAINT "FK_defects_defect_statuses_defect_status_id" FOREIGN KEY (defect_status_id) REFERENCES defect_statuses (id) ON DELETE RESTRICT,
        CONSTRAINT "FK_defects_projects_project_id" FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
        CONSTRAINT "FK_defects_test_cases_test_case_id" FOREIGN KEY (test_case_id) REFERENCES test_cases (id) ON DELETE SET NULL,
        CONSTRAINT "FK_defects_test_executions_test_execution_id" FOREIGN KEY (test_execution_id) REFERENCES test_executions (id) ON DELETE SET NULL,
        CONSTRAINT "FK_defects_users_assigned_to_user_id" FOREIGN KEY (assigned_to_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_defects_users_reported_by_user_id" FOREIGN KEY (reported_by_user_id) REFERENCES users (id) ON DELETE RESTRICT
    );
    END IF;
END $EF$;

