DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260719182705_AddSystemsUnderTestAndIndexes') THEN
    CREATE TABLE systems_under_test (
        id uuid NOT NULL,
        project_id uuid NOT NULL,
        name character varying(150) NOT NULL,
        description character varying(1000),
        version character varying(50),
        environment character varying(50),
        base_url character varying(255),
        is_active boolean NOT NULL DEFAULT TRUE,
        is_deleted boolean NOT NULL DEFAULT FALSE,
        deleted_at timestamp with time zone,
        deleted_by_user_id uuid,
        created_at timestamp with time zone NOT NULL,
        created_by_user_id uuid,
        updated_at timestamp with time zone,
        updated_by_user_id uuid,
        CONSTRAINT "PK_systems_under_test" PRIMARY KEY (id),
        CONSTRAINT "FK_systems_under_test_projects_project_id" FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
        CONSTRAINT "FK_systems_under_test_users_created_by_user_id" FOREIGN KEY (created_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_systems_under_test_users_deleted_by_user_id" FOREIGN KEY (deleted_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_systems_under_test_users_updated_by_user_id" FOREIGN KEY (updated_by_user_id) REFERENCES users (id) ON DELETE SET NULL
    );
    END IF;
END $EF$;

