    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260719205014_AddTestPlanIstqbFeatures') THEN
    ALTER TABLE test_plans ADD "TestStrategy" text;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260719205014_AddTestPlanIstqbFeatures') THEN
    CREATE TABLE api_keys (
        id uuid NOT NULL,
        project_id uuid NOT NULL,
        name character varying(100) NOT NULL,
        key_hash character varying(256) NOT NULL,
        key_prefix character varying(16) NOT NULL,
        is_active boolean NOT NULL DEFAULT TRUE,
        expires_at timestamp with time zone,
        last_used_at timestamp with time zone,
        created_at timestamp with time zone NOT NULL,
        created_by_user_id uuid,
        updated_at timestamp with time zone,
        updated_by_user_id uuid,
        is_deleted boolean NOT NULL DEFAULT FALSE,
        deleted_at timestamp with time zone,
        deleted_by_user_id uuid,
        CONSTRAINT "PK_api_keys" PRIMARY KEY (id),
        CONSTRAINT "FK_api_keys_projects_project_id" FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
        CONSTRAINT "FK_api_keys_users_created_by_user_id" FOREIGN KEY (created_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_api_keys_users_deleted_by_user_id" FOREIGN KEY (deleted_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_api_keys_users_updated_by_user_id" FOREIGN KEY (updated_by_user_id) REFERENCES users (id) ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260719205014_AddTestPlanIstqbFeatures') THEN
    CREATE TABLE test_plan_criteria (
        "Id" uuid NOT NULL,
        "TestPlanId" uuid NOT NULL,
        "CriteriaType" character varying(20) NOT NULL,
        "Description" character varying(1000) NOT NULL,
        "IsMet" boolean NOT NULL DEFAULT FALSE,
        "CreatedAt" timestamp with time zone NOT NULL,
        "CreatedByUserId" uuid,
        "UpdatedAt" timestamp with time zone,
        "UpdatedByUserId" uuid,
        CONSTRAINT "PK_test_plan_criteria" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_test_plan_criteria_test_plans_TestPlanId" FOREIGN KEY ("TestPlanId") REFERENCES test_plans ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_test_plan_criteria_users_CreatedByUserId" FOREIGN KEY ("CreatedByUserId") REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_test_plan_criteria_users_UpdatedByUserId" FOREIGN KEY ("UpdatedByUserId") REFERENCES users (id) ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
