DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260801004658_AddStaticTestingModule') THEN
    CREATE TABLE review_sessions (
        id uuid NOT NULL,
        project_id uuid NOT NULL,
        title character varying(200) NOT NULL,
        description character varying(2000),
        artifact_under_review character varying(500),
        review_type_id integer NOT NULL,
        status_id integer NOT NULL,
        scheduled_date timestamp with time zone,
        completed_date timestamp with time zone,
        moderator_id uuid,
        author_id uuid,
        entry_criteria character varying(1000),
        exit_criteria character varying(1000),
        conclusions character varying(2000),
        is_deleted boolean NOT NULL DEFAULT FALSE,
        deleted_at timestamp with time zone,
        deleted_by_user_id uuid,
        created_at timestamp with time zone NOT NULL,
        created_by_user_id uuid,
        updated_at timestamp with time zone,
        updated_by_user_id uuid,
        CONSTRAINT "PK_review_sessions" PRIMARY KEY (id),
        CONSTRAINT "FK_review_sessions_projects_project_id" FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
        CONSTRAINT "FK_review_sessions_review_statuses_status_id" FOREIGN KEY (status_id) REFERENCES review_statuses ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_review_sessions_review_types_review_type_id" FOREIGN KEY (review_type_id) REFERENCES review_types ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_review_sessions_users_author_id" FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_review_sessions_users_created_by_user_id" FOREIGN KEY (created_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_review_sessions_users_deleted_by_user_id" FOREIGN KEY (deleted_by_user_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_review_sessions_users_moderator_id" FOREIGN KEY (moderator_id) REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_review_sessions_users_updated_by_user_id" FOREIGN KEY (updated_by_user_id) REFERENCES users (id) ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
