        CONSTRAINT "PK_review_findings" PRIMARY KEY (id),
        CONSTRAINT "FK_review_findings_finding_severities_severity_id" FOREIGN KEY (severity_id) REFERENCES finding_severities ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_review_findings_finding_statuses_finding_status_id" FOREIGN KEY (finding_status_id) REFERENCES finding_statuses ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_review_findings_finding_types_finding_type_id" FOREIGN KEY (finding_type_id) REFERENCES finding_types ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_review_findings_review_sessions_review_session_id" FOREIGN KEY (review_session_id) REFERENCES review_sessions (id) ON DELETE CASCADE,
        CONSTRAINT "FK_review_findings_users_assigned_to_id" FOREIGN KEY (assigned_to_id) REFERENCES users (id) ON DELETE SET NULL,
