DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260801004658_AddStaticTestingModule') THEN
    PERFORM setval(
        pg_get_serial_sequence('finding_severities', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM finding_severities) + 1,
            nextval(pg_get_serial_sequence('finding_severities', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('finding_statuses', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM finding_statuses) + 1,
            nextval(pg_get_serial_sequence('finding_statuses', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('finding_types', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM finding_types) + 1,
            nextval(pg_get_serial_sequence('finding_types', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('review_statuses', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM review_statuses) + 1,
            nextval(pg_get_serial_sequence('review_statuses', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('review_types', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM review_types) + 1,
            nextval(pg_get_serial_sequence('review_types', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('test_design_techniques', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM test_design_techniques) + 1,
            nextval(pg_get_serial_sequence('test_design_techniques', 'Id'))),
        false);
    END IF;
END $EF$;

