        CONSTRAINT "PK_exploratory_sessions" PRIMARY KEY (id),
        CONSTRAINT "FK_exploratory_sessions_projects_project_id" FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
        CONSTRAINT "FK_exploratory_sessions_users_CreatedByUserId" FOREIGN KEY ("CreatedByUserId") REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_exploratory_sessions_users_DeletedByUserId" FOREIGN KEY ("DeletedByUserId") REFERENCES users (id) ON DELETE SET NULL,
        CONSTRAINT "FK_exploratory_sessions_users_UpdatedByUserId" FOREIGN KEY ("UpdatedByUserId") REFERENCES users (id) ON DELETE SET NULL,
